import React from 'react';

export default function Header() {
  return (
    <>
      <style>
        {`
          @keyframes rgbGlow {
            0% { filter: hue-rotate(0deg); }
            100% { filter: hue-rotate(360deg); }
          }

          .rgb-icon {
            animation: rgbGlow 4s linear infinite;
          }

          .nav-link {
            position: relative;
            transition: color 0.3s ease;
          }

          .nav-link:hover {
            color: #00D2C4 !important;
          }

          .nav-link::after {
            content: '';
            position: absolute;
            width: 0;
            height: 2px;
            bottom: -4px;
            left: 0;
            background-color: #00D2C4;
            transition: width 0.3s ease;
          }

          .nav-link:hover::after {
            width: 100%;
          }

          .cta-button {
            transition: all 0.3s ease !important;
          }

          .cta-button:hover {
            background-color: #00ffe0 !important;
            transform: translateY(-2px);
            box-shadow: 0 4px 20px rgba(0, 210, 196, 0.4);
          }
        `}
      </style>

      <nav style={{
        backgroundColor: '#070F1E',
        borderBottom: '1px solid rgba(255, 255, 255, 0.05)',
        padding: '16px 32px',
        display: 'flex',
        justifyContent: 'space-between',
        alignItems: 'center',
        position: 'sticky',
        top: 0,
        zIndex: 50
      }}>
        {/* Logo Section */}
        <div style={{ display: 'flex', alignItems: 'center', gap: '12px', cursor: 'pointer' }}>
          <div className="rgb-icon" style={{
            width: '38px',
            height: '38px',
            borderRadius: '10px',
            background: 'linear-gradient(135deg, #00D2C4, #7928CA, #FF0080)',
            backgroundSize: '200% 200%',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            color: '#fff',
            fontWeight: 'bold',
            boxShadow: '0 0 15px rgba(0, 210, 196, 0.3)'
          }}>
            VA
          </div>
          <span style={{ color: '#fff', fontSize: '18px', fontWeight: 'bold', letterSpacing: '0.5px' }}>
            Vighnavi Academy
          </span>
        </div>

        {/* Navigation Links */}
        <div style={{ display: 'flex', gap: '28px', fontSize: '14px', fontWeight: '500' }}>
          <a href="#home" className="nav-link" style={{ color: '#d1d5db', textDecoration: 'none' }}>Home</a>
          <a href="#about" className="nav-link" style={{ color: '#d1d5db', textDecoration: 'none' }}>About Us</a>
          <a href="#courses" className="nav-link" style={{ color: '#d1d5db', textDecoration: 'none' }}>Courses</a>
          <a href="#testimonials" className="nav-link" style={{ color: '#d1d5db', textDecoration: 'none' }}>Testimonials</a>
        </div>

        {/* CTA Button */}
        <div>
          <a href="#contact" className="cta-button" style={{
            backgroundColor: '#00D2C4',
            color: '#000',
            padding: '10px 22px',
            borderRadius: '20px',
            textDecoration: 'none',
            fontWeight: '600',
            fontSize: '14px',
            display: 'inline-block'
          }}>
            Book Consultation
          </a>
        </div>
      </nav>
    </>
  );
}
